export function translateString(raw, lang) {
  if (!raw || lang === "en") return raw;
  const trimmed = raw.trim();
  if (!trimmed) return raw;

  const exact = EXACT_I18N[trimmed];
  if (exact && exact[lang]) {
    return raw.replace(trimmed, exact[lang]);
  }

  for (const rule of REGEX_I18N) {
    if (rule.re.test(trimmed) && rule[lang]) {
      const replaced = trimmed.replace(rule.re, rule[lang]);
      return raw.replace(trimmed, replaced);
    }
  }
  return raw;
}

/**
 * Walks all text nodes and input/textarea placeholders under `root` and translates them
 * according to `lang` ('en' | 'ur' | 'ro-ur'). Preserves original English on each node
 * so toggling back to 'en' is 100% lossless.
 */
export function translateDOM(root, lang) {
  if (!root) return;

  // 1. Translate placeholders
  root.querySelectorAll("input[placeholder], textarea[placeholder]").forEach((el) => {
    if (el.__origPlaceholder === undefined) {
      el.__origPlaceholder = el.getAttribute("placeholder") || "";
    }
    const orig = el.__origPlaceholder;
    el.setAttribute("placeholder", lang === "en" ? orig : translateString(orig, lang));
  });

  // 2. Walk text nodes
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent) return NodeFilter.FILTER_REJECT;
      const tag = parent.tagName;
      if (tag === "SCRIPT" || tag === "STYLE" || tag === "CODE" || tag === "PRE" || tag === "TEXTAREA") {
        return NodeFilter.FILTER_REJECT;
      }
      if (parent.classList?.contains("material-symbols-outlined")) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });

  const nodes = [];
  let current = walker.nextNode();
  while (current) {
    nodes.push(current);
    current = walker.nextNode();
  }

  for (const node of nodes) {
    const val = node.nodeValue || "";
    if (!val.trim()) continue;
    // If the node was dynamically updated by JS (e.g., health status or breadcrumb), refresh __origText when in EN or when it matches an English pattern
    const trimmed = val.trim();
    if (
      node.__origText === undefined ||
      (EXACT_I18N[trimmed] !== undefined) ||
      REGEX_I18N.some((r) => r.re.test(trimmed))
    ) {
      node.__origText = val;
    }
    const orig = node.__origText;
    node.nodeValue = lang === "en" ? orig : translateString(orig, lang);
  }
}
